package com.framerevive.app

/** Presentation only. All owner/Google text is escaped; HTML fragments come from our own renderers. */
object FrameWeb {
    const val VERSION = "0.5.15-alpha"
    data class Album(val id: String, val title: String)
    data class State(val text: Map<String, String>, val flags: Set<String>, val albums: List<Album> = emptyList(),
                     val updateHtml: String = "", val recoveryHtml: String = "")
    fun render(state: State): String {
        fun has(name: String) = name in state.flags
        fun value(name: String) = FrameRemote.escape(state.text[name].orEmpty())
        fun checked(name: String) = if (has(name)) "checked" else ""
        val needsSetup = has("needsSetup")
        val attention = !state.text["syncError"].isNullOrBlank() || !state.text["countError"].isNullOrBlank()
        val tone = if (needsSetup || attention) "attention" else "healthy"
        val health = when { needsSetup -> "No album connected"; attention -> "Connection needs attention"; has("syncing") -> "Refreshing your album"; else -> "Working normally" }
        val detail = when { needsSetup -> "Connect an album in Setup to get started."; attention -> "Your saved photos can keep playing. Check Debug for details."; has("syncing") -> "The slideshow keeps playing while your album updates."; else -> "Album connected. Automatic checks enabled." }
        val source = if (has("shared")) "Shared album" else "Signed-in album"
        val options = state.albums.joinToString("") { "<option value=\"${FrameRemote.escape(it.id)}\" ${if(it.id == state.text["albumId"]) "selected" else ""}>${FrameRemote.escape(it.title)}</option>" }
        return """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>FrameRevive · Your frame</title><style>$style</style></head><body>
        <div class="shell"><header class="brand"><a class="brand-home" href="#everyday" aria-label="FrameRevive home"><span class="brand-mark" aria-hidden="true"><i></i></span><span>Frame<span class="brand-light">Revive</span></span></a><span class="version">$VERSION</span></header>
        <nav class="tabs" role="tablist" aria-label="Frame controls"><button type="button" id="tab-everyday" role="tab" aria-controls="everyday" aria-selected="true" data-tab="everyday">Everyday</button><button type="button" id="tab-setup" role="tab" aria-controls="setup" aria-selected="false" tabindex="-1" data-tab="setup">Setup</button><button type="button" id="tab-debug" role="tab" aria-controls="debug" aria-selected="false" tabindex="-1" data-tab="debug">Debug &amp; updates</button></nav>
        <main>
        <section id="everyday" class="tab-panel" role="tabpanel" aria-labelledby="tab-everyday">
          <div class="page-heading"><h1>Frame controls</h1><p>Playback, display and sleep settings.</p></div>
          <div id="everydayStatus" class="health $tone" role="status"><span class="status-dot" aria-hidden="true"></span><div><strong>$health</strong><p>$detail</p></div>${if(needsSetup || attention) "<a class='text-link' href='#${if(needsSetup) "setup" else "debug"}'>${if(needsSetup) "Open setup" else "View details"} ↗</a>" else ""}</div>
          <article class="card now-card"><div class="card-heading"><span class="eyebrow">ALBUM</span><span class="source-tag">$source</span></div><div id="albumSummary"><h2 class="album-title">${value("title")}</h2><div class="metrics"><div><strong>${value("photoCount")}</strong><span>photos</span></div><div><strong>${value("pending")}</strong><span>waiting to display</span></div></div><p class="muted">New additions first, then recent photos and memories from this time in years past.</p><p class="last-updated">Last refreshed · ${value("lastSync")}</p></div>
          <div id="playbackState"><p class="muted">Playback: <strong>${if(has("paused")) "Paused" else "Playing"}</strong>${if(has("photoLoading")) " · Loading photo…" else ""}</p><form method="post"><button name="action" value="${if(has("paused")) "resume" else "pause"}" class="secondary">${if(has("paused")) "Resume slideshow" else "Pause slideshow"}</button></form></div><form method="post" class="playback-actions"><button name="action" value="previous" class="secondary"><span aria-hidden="true">←</span> Previous</button><button name="action" value="next" class="primary">Next photo <span aria-hidden="true">→</span></button><button name="action" value="refresh" class="quiet">↻ Refresh album</button></form></article>
          <form method="post" id="displaySettings"><div class="settings-grid">
            <article class="card"><h2>Playback &amp; display</h2><label>Seconds per photo<input type="number" min="10" max="300" required name="seconds" value="${value("seconds")}"><small>Choose between 10 and 300 seconds.</small></label><label>Daytime brightness<span class="input-unit"><input type="number" min="5" max="100" required name="brightness" value="${value("brightness")}"><span>%</span></span></label>
            <label class="toggle"><span><strong>Fill the screen</strong><small>Crop the edges to fill the frame.</small></span><input type="checkbox" name="crop" ${checked("crop")}></label><label class="toggle"><span><strong>Blurred photo background</strong><small>Fill unused space with a blurred copy. Turn Fill the screen off to show the full photo.</small></span><input type="checkbox" name="blurBackground" ${checked("blurBackground")}></label><input type="hidden" name="backgroundSettings" value="1"><label class="toggle"><span><strong>Photo dates</strong><small>Show the photo capture date.</small></span><input type="checkbox" name="date" ${checked("date")}></label></article>
            <article class="card"><h2>Sleep schedule</h2><div id="frameClock" class="soft-note"><strong>Frame time: ${value("frameTime")}</strong><br>Time zone: ${value("frameTimeZone")}<br><small>Read from the frame; updates with status every 15 seconds.</small></div><label class="toggle"><span><strong>Nightly sleep schedule</strong><small>Uses the frame's local time.</small></span><input type="checkbox" name="schedule" ${checked("schedule")}></label><div class="field-grid"><label>Sleep at<input type="time" required name="sleepStart" value="${value("sleepStart")}"></label><label>Wake at<input type="time" required name="sleepEnd" value="${value("sleepEnd")}"></label></div><div class="soft-note">${if(has("hardwareSleep")) "Your frame turns its display off and wakes automatically." else "Sleep dims to black. Hardware display control is not enabled."}</div>
            <label class="toggle gesture-toggle"><span><strong>Hand gestures</strong><small>Left for next. Right for previous.</small></span><input type="checkbox" name="gestures" ${checked("gestures")}></label><input type="hidden" name="gestureSettings" value="1"></article>
          </div><div class="save-bar"><span>Changes apply when you save.</span><button name="action" value="save" class="primary">Save settings <span aria-hidden="true">✓</span></button></div></form>
          <p class="page-note">Add photos in Google Photos as usual. Shared albums are checked every two minutes while your frame is awake.</p>
        </section>
        <section id="setup" class="tab-panel" role="tabpanel" aria-labelledby="tab-setup" hidden>
          <div class="page-heading"><h1>Setup</h1><p>Connect an album and save your controls link.</p></div>
          <article class="card"><div class="card-heading"><h2>Connect a shared album</h2><span class="source-tag">Recommended</span></div><p class="muted">Use an album link that opens without signing in. No Google account cookies are needed.</p><p id="setupStatus" class="soft-note" data-busy="${has("busy")}">${value("setupMessage")}</p><form method="post"><label>Google Photos album link<input type="url" required name="sharedLink" placeholder="https://photos.app.goo.gl/…" autocomplete="off"></label><button name="action" value="sharedAlbum" class="primary">Connect album →</button></form><p class="fine-print">Anyone with the shared link can view its photos. Keep it private. Your existing album keeps playing until a new album finishes loading.</p></article>
          <article class="card"><details ${if(needsSetup && !has("shared")) "open" else ""}><summary>Use a signed-in Google Photos session<span>Alternative setup</span></summary><p>Sign in only on Google's own website. This imports a local session export, not Google's official Sign in button.</p><ol><li>Install <a href="https://chromewebstore.google.com/detail/get-cookiestxt-locally/cclelndahbckbenkjhflpdbgdldlbecc" target="_blank" rel="noreferrer noopener">Get cookies.txt LOCALLY</a> on your computer and allow it in Incognito.</li><li>In a new Incognito window, sign in at <a href="https://photos.google.com/" target="_blank" rel="noreferrer noopener">Google Photos</a>.</li><li>Open a blank tab, close the Photos tab, then use the extension's <strong>Export All Cookies</strong> button with Netscape format.</li><li>Close Incognito, select the export below and import it.</li></ol><p class="fine-print">The file contains sign-in credentials. Use only your verified HTTPS controls page on trusted home Wi-Fi. The frame filters, validates and encrypts the session. Never share the export or upload it to GitHub; delete it after successful setup.</p><label for="sessionFile">Session export</label><input id="sessionFile" type="file" accept=".txt,text/plain"><button type="button" id="importButton" class="primary">Import session</button><p id="importResult" role="status"></p><form method="post"><button name="action" value="loadAlbums" class="secondary">Load my albums</button></form><div id="albumPicker">${if(state.albums.isNotEmpty()) "<form method='post'><label>Display album<select name='albumId'>$options</select></label><button name='action' value='selectAlbum' class='primary'>Use this album</button></form>" else ""}</div></details></article>
          <article class="card"><h2>Controls address</h2><p class="muted">Bookmark this full private link. The local name stays the same when the frame's IP changes.</p><a class="bookmark" href="${value("bookmark")}">${value("bookmark")}</a><p class="fine-print">${value("hostnameStatus")}</p><details><summary>HTTPS pairing &amp; network help</summary><p>Each frame has its own certificate. Before trusting it for the first time, compare the certificate SHA-256 fingerprint with the one shown on the physical frame or obtained over authorized USB. Never accept an unexpected replacement without checking.</p><p class="fine-print">The fingerprint displayed on this page is useful only after you have verified the connection.</p><code class="fingerprint">${value("fingerprint")}</code><p>Use the same home Wi-Fi. Guest-network isolation can block access. If .local names are unavailable, use your original IP link or configure local DNS/a router reservation; a changed IP might not match the original certificate.</p></details></article>
        </section>
        <section id="debug" class="tab-panel" role="tabpanel" aria-labelledby="tab-debug" hidden>
          <div class="page-heading"><h1>Debug &amp; updates</h1><p>Connection status, diagnostics and app updates.</p></div>
          <article class="card"><div class="card-heading"><h2>Connection &amp; activity</h2><span class="source-tag">Live status</span></div><div id="connectionStatus"><dl class="status-list"><div><dt>Source</dt><dd>$source${if(has("shared")) " · no account cookies" else ""}</dd></div><div><dt>Last successful refresh</dt><dd>${value("lastSync")}</dd></div><div><dt>Last attempt</dt><dd>${value("lastAttempt")}</dd></div><div><dt>Refresh</dt><dd>${if(has("syncing")) "In progress" else "Idle · hourly full checks"}</dd></div><div><dt>Count check</dt><dd>${value("countCheck")}</dd></div><div><dt>Observed count</dt><dd>${value("observedCount")}</dd></div></dl><div class="error-note">${if(attention) "<strong>Needs attention</strong><p>${value("syncError")}</p><p>${value("countError")}</p>" else "No current album refresh error."}</div>${if(!state.text["photoError"].isNullOrBlank()) "<details class='past-error'><summary>Last recorded photo error</summary><p>${value("photoErrorAt")} · ${value("photoError")}</p><p>Cached photos may continue playing. This is the last recorded error, not necessarily a current failure.</p></details>" else ""}</div><div id="gestureStatus" class="activity-line"><span class="status-dot"></span><p>Last hand gesture: <strong>${value("lastGesture")}</strong><small>${value("lastGestureAt")}</small></p></div><div id="powerStatus" class="soft-note">Last power event: ${value("powerEvent")}<br>Next wake: ${value("nextWake")}</div></article>
          <article class="card"><div class="card-heading"><h2>Diagnostics</h2><button type="button" id="copyDiagnostics" class="secondary">Copy diagnostics</button></div><p class="muted">A useful summary for troubleshooting. Private album links, photo URLs, controls keys and account cookies are left out.</p><pre id="diagnosticReport" tabindex="0">${value("diagnostics")}</pre></article>
          <article class="card"><h2>App update</h2><div id="updateStatus" role="status">${state.updateHtml}</div><p class="muted">Upload a FrameRevive APK, up to 40 MiB. The frame checks it first. Android still asks you to confirm installation on the frame with your Bluetooth mouse.</p><label for="apkFile">APK file</label><input type="file" id="apkFile" accept=".apk,application/vnd.android.package-archive"><button type="button" id="apkUpload" class="primary">Upload &amp; verify APK</button><form method="post" class="button-row"><button name="action" value="allowInstalls" class="secondary">Allow installs on frame</button><button name="action" value="installApk" class="secondary">Install on frame</button><button name="action" value="discardApk" class="quiet">Discard upload</button></form></article>
          <article class="card project-card"><div><h2>Project &amp; downloads</h2><p class="muted">Source code, guides and available release downloads.</p></div><div class="button-row"><a class="button secondary" href="https://github.com/letsteststuff/FrameRevive" target="_blank" rel="noreferrer noopener">GitHub repository ↗</a><a class="button primary" href="https://github.com/letsteststuff/FrameRevive/releases" target="_blank" rel="noreferrer noopener">Releases &amp; downloads ↗</a></div><p class="fine-print">Installed on this frame: $VERSION. GitHub downloads may be an earlier published version.</p></article>
          <article class="card recovery">${state.recoveryHtml}</article>
        </section>
        </main><div id="actionResult" role="status" aria-live="polite" class="action-result"></div><footer><span class="footer-mark">FrameRevive</span><span>$VERSION · Private home controls</span></footer></div>
        <script>$script</script></body></html>""".trimIndent()
    }

    private val style = """
    :root{color-scheme:dark;--bg:#15171b;--card:#1e2127;--card2:#252932;--line:#383e48;--text:#edf0f5;--muted:#b0b7c3;--accent:#90b8f8;--highlight:#e4bd7a;--ink:#10213b}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.6 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}button,input,select{font:inherit}button,a,input,select,summary{touch-action:manipulation}a{color:var(--accent);text-underline-offset:4px}button,.button{cursor:pointer;border:1px solid transparent;border-radius:12px;min-height:48px;padding:12px 19px;display:inline-flex;align-items:center;justify-content:center;gap:12px;font-size:14px;font-weight:650;line-height:1.4;transition:background .18s,transform .18s;text-decoration:none}button:hover,.button:hover{filter:brightness(1.08)}button:active,.button:active{transform:translateY(1px)}button:disabled{opacity:.65;cursor:wait}button[aria-busy=true]:before{content:'';display:inline-block;width:13px;height:13px;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;animation:spin .8s linear infinite}.primary{background:var(--accent);color:var(--ink)}.secondary{background:#2b3039;border-color:#46505e;color:var(--text)}.quiet{background:transparent;color:var(--muted)}:focus-visible{outline:3px solid var(--highlight);outline-offset:4px}[hidden]{display:none!important}.shell{max-width:1060px;margin:auto;padding:35px 36px 20px}.brand{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-bottom:30px}.brand-home{display:flex;gap:14px;align-items:center;text-decoration:none;color:var(--text);font-size:24px;font-weight:700;letter-spacing:-1px;line-height:1.1}.brand-light{font-weight:350}.brand small{display:block;font-size:8px;font-weight:600;letter-spacing:2.5px;color:var(--muted);margin-top:8px}.brand-mark{width:44px;height:48px;border:1px solid #596577;display:grid;place-items:center;border-radius:9px;background:#262c35}.brand-mark i{width:27px;height:31px;border:2px solid var(--accent);border-radius:3px;position:relative;overflow:hidden}.brand-mark i:after{content:'';position:absolute;width:25px;height:20px;background:var(--highlight);border-radius:50%;top:13px;left:-8px}.version,.source-tag{border:1px solid var(--line);padding:5px 11px;border-radius:30px;color:var(--muted);font-size:11px;white-space:nowrap}.tabs{display:flex;padding:6px;border:1px solid var(--line);background:#1b1e24;border-radius:12px;gap:5px;position:sticky;top:10px;z-index:10;box-shadow:0 12px 24px #0002}.tabs button{flex:1;color:var(--muted);background:transparent;min-height:45px;padding:10px 8px;font-size:14px}.tabs button[aria-selected=true]{background:var(--accent);color:var(--ink);box-shadow:0 2px 9px #0002}.page-heading{padding:26px 0 20px}.eyebrow,.section-number{font-size:10px;font-weight:650;letter-spacing:2.1px;color:var(--highlight);margin:0 0 12px}.page-heading h1{font-weight:600;font-size:30px;line-height:1.25;letter-spacing:-.6px;margin:0 0 17px}.page-heading>p:last-child{color:var(--muted);font-size:14px;margin-bottom:0}.health{display:flex;align-items:center;gap:15px;background:#202a38;border:1px solid #3b4d66;padding:18px 22px;border-radius:15px;margin:0 0 24px}.status-dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 5px #90b8f812;flex-shrink:0}.health strong{font-size:14px}.health p{font-size:12px;margin:3px 0 0;color:var(--muted)}.health .text-link{font-size:12px;margin-left:auto;white-space:nowrap}.health.attention{background:#3a3021;border-color:#6c5834}.attention .status-dot{background:var(--highlight)}.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:28px;margin-bottom:22px}.card-heading{display:flex;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap}.card-heading>.eyebrow{margin:0}.card h2{font-size:20px;font-weight:550;letter-spacing:-.4px;line-height:1.35;margin:0 0 12px}.card-heading h2{margin:0}.card p{font-size:14px}.card .album-title{font-size:25px;font-weight:550;margin:22px 0}.metrics{display:flex;gap:40px;margin:12px 0 20px}.metrics>div{padding-right:35px;border-right:1px solid var(--line)}.metrics>div:last-child{border:0;padding-right:0}.metrics strong{font-size:31px;line-height:1.3;font-weight:450;letter-spacing:-1px;display:block}.metrics span{display:block;color:var(--muted);font-size:12px;margin-top:3px}.muted{color:var(--muted);font-size:14px}.last-updated{color:var(--muted);font-size:11px!important}.playback-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px;padding-top:24px;border-top:1px solid var(--line)}.playback-actions .quiet{margin-left:auto}.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.settings-grid .card{margin:0}label{display:block;font-size:13px;color:var(--muted);margin:22px 0}label small,.fine-print{display:block;color:#aab3c0;font-size:11px;line-height:1.7}label small{margin-top:6px}input:not([type=checkbox]),select{display:block;width:100%;min-height:48px;background:#171a20;border:1px solid #454d5b;border-radius:10px;padding:10px 12px;color:var(--text);margin:8px 0 0;min-width:0;max-width:100%}input::placeholder{color:#8792a4}input[type=file]{font-size:12px;margin-bottom:17px}input::file-selector-button{background:#343d4b;color:var(--text);border:0;border-radius:6px;padding:7px 10px;margin-right:10px}.input-unit{display:block;position:relative}.input-unit input{padding-right:40px}.input-unit>span{position:absolute;right:15px;top:12px}.toggle{display:flex;gap:20px;align-items:center;justify-content:space-between;border-top:1px solid var(--line);padding-top:19px;margin:20px 0 0}.toggle strong{font-size:13px;color:var(--text);font-weight:500}.toggle small{font-size:11px;margin-top:2px}.toggle input{appearance:none;-webkit-appearance:none;flex-shrink:0;width:43px;height:25px;background:#444c59;border:1px solid #657184;border-radius:25px;position:relative;cursor:pointer;margin:0}.toggle input:before{content:'';position:absolute;left:3px;top:3px;width:17px;height:17px;border-radius:50%;background:#d6dce6;transition:transform .15s}.toggle input:checked{background:var(--accent);border-color:var(--accent)}.toggle input:checked:before{background:var(--ink);transform:translateX(17px)}.field-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.soft-note{background:#1a2029;padding:15px 17px;border:1px solid #364152;border-radius:11px;font-size:12px;color:var(--muted);line-height:1.7;overflow-wrap:anywhere}.gesture-toggle{margin-top:24px}.save-bar{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:20px 3px 0}.save-bar>span{font-size:12px;color:var(--muted)}.page-note{font-size:11px;color:var(--muted);text-align:center;margin:25px 0 35px}.button-row{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:18px}.bookmark,.fingerprint{display:block;overflow-wrap:anywhere;background:#171d25;padding:16px;border:1px solid var(--line);border-radius:10px;font:12px/1.8 ui-monospace,monospace}.bookmark{color:var(--accent)}details>summary{cursor:pointer;min-height:44px;padding:9px 0;color:var(--text);font-size:14px;font-weight:550}details>summary span{display:block;font-size:11px;color:var(--muted);font-weight:400;margin-left:16px}.card details p,.card li{font-size:13px;color:var(--muted)}li{margin-bottom:12px;padding-left:4px}ol{padding-left:23px}.card details details{border-top:1px solid var(--line)}.status-list{margin:16px 0}.status-list>div{display:flex;gap:20px;justify-content:space-between;padding:10px 0;border-bottom:1px solid #383e4888;font-size:12px}.status-list dt{color:var(--muted)}.status-list dd{text-align:right;margin:0;max-width:65%;overflow-wrap:anywhere}.error-note{font-size:12px;color:var(--muted);padding:12px 0}.error-note p:empty{display:none}.error-note strong{color:var(--highlight)}.past-error{border-top:1px solid var(--line)}.activity-line{display:flex;gap:15px;align-items:center;border-top:1px solid var(--line);padding:10px 0}.activity-line p{font-size:12px}.activity-line small{display:block;color:var(--muted);margin-top:4px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#171b22;border:1px solid var(--line);border-radius:10px;padding:18px;font:11px/1.9 ui-monospace,monospace;color:#c3cddc;max-height:380px;overflow:auto}.recovery pre{font-family:inherit;font-size:12px;background:transparent;border:0;padding:0;max-height:none}.project-card{border-color:#383e48}.action-result{position:sticky;bottom:14px;z-index:12;background:#253951;color:#edf0f5;padding:13px 18px;border-radius:12px;box-shadow:0 8px 30px #0005;font-size:13px;max-width:740px;margin:0 auto}.action-result:empty{display:none}footer{display:flex;justify-content:space-between;gap:15px;border-top:1px solid var(--line);padding:25px 0;color:#9ba7b8;font-size:10px;flex-wrap:wrap}.footer-mark{font-weight:650;color:#c1cad7;font-size:12px}@keyframes spin{to{transform:rotate(360deg)}}@media(min-width:850px){.page-heading h1 br{display:none}.page-heading{padding-top:26px}.now-card{padding:32px}.metrics{gap:60px}}@media(max-width:640px){.shell{padding:23px 18px 16px}.brand{padding-bottom:22px}.brand-home{font-size:21px}.brand small{font-size:7px;letter-spacing:1.7px}.brand-mark{width:37px;height:41px}.brand-mark i{width:23px;height:27px}.version{font-size:9px;padding:4px 8px}.tabs{top:8px}.tabs button{font-size:12px;padding:10px 4px}.page-heading{padding:32px 2px 23px}.page-heading h1{font-size:28px}.card{padding:22px 20px;border-radius:12px}.health{padding:16px;gap:12px;align-items:flex-start;flex-wrap:wrap}.health>.status-dot{margin-top:8px}.health>div{flex:1}.health .text-link{margin-left:20px}.settings-grid{grid-template-columns:1fr;gap:18px}.metrics{gap:24px}.metrics>div{padding-right:24px}.metrics strong{font-size:29px}.playback-actions{gap:8px}.playback-actions>.primary,.playback-actions>.secondary{flex:1}.playback-actions>.quiet{margin:auto;min-height:35px;padding:8px}.save-bar{align-items:flex-start}.save-bar>span{max-width:120px;padding-top:7px}.page-note{padding:0 12px}.card-heading{gap:12px}.card h2{font-size:19px}.card .album-title{font-size:24px}.card-heading #copyDiagnostics{width:100%}.button-row>*{flex-grow:1}.status-list>div{gap:12px}.status-list dd{max-width:58%}.source-tag{font-size:10px}.project-card .button-row{display:grid;grid-template-columns:1fr}footer{justify-content:center;text-align:center}footer>span:last-child{width:100%}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important;animation:none!important}}
    """.trimIndent()

    private val script = """
    const result=document.getElementById('actionResult');let sending=false;let timer;
    const names=['everyday','setup','debug'];
    function selectTab(name,focus=false){if(!names.includes(name))name='everyday';for(const n of names){const b=document.getElementById('tab-'+n);b.setAttribute('aria-selected',String(n===name));b.tabIndex=n===name?0:-1;document.getElementById(n).hidden=n!==name;}if(focus)document.getElementById('tab-'+name).focus();}
    function fromHash(){selectTab(location.hash.slice(1));}fromHash();window.addEventListener('hashchange',fromHash);
    document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{history.replaceState(null,'','#'+b.dataset.tab);selectTab(b.dataset.tab);}));
    document.querySelector('[role=tablist]').addEventListener('keydown',event=>{let i=names.indexOf(document.activeElement.dataset.tab);if(i<0)return;if(event.key==='ArrowRight')i=(i+1)%3;else if(event.key==='ArrowLeft')i=(i+2)%3;else if(event.key==='Home')i=0;else if(event.key==='End')i=2;else return;event.preventDefault();history.replaceState(null,'','#'+names[i]);selectTab(names[i],true);});
    function busy(button,on){button.disabled=on;button.setAttribute('aria-busy',String(on));}
    async function updateStatus(){
      const response=await fetch(location.href,{cache:'no-store'});if(!response.ok)throw new Error('Could not read frame status.');
      const page=new DOMParser().parseFromString(await response.text(),'text/html');
      for(const id of ['setupStatus','albumSummary','albumPicker','powerStatus','connectionStatus','updateStatus','gestureStatus','everydayStatus','diagnosticReport','frameClock','playbackState']){
        const fresh=page.getElementById(id),current=document.getElementById(id);
        if(fresh&&current){if(id==='albumPicker'&&document.activeElement&&current.contains(document.activeElement))continue;const selection=window.getSelection();if(id==='diagnosticReport'&&selection&&!selection.isCollapsed&&selection.containsNode(current,true))continue;if(current.outerHTML!==fresh.outerHTML)current.replaceWith(fresh);}
      }
      clearTimeout(timer);timer=setTimeout(poll,document.getElementById('setupStatus').dataset.busy==='true'?4000:15000);
    }
    async function poll(){try{await updateStatus();}catch(error){result.textContent='Connection interrupted. Retrying automatically…';timer=setTimeout(poll,5000);}}
    async function send(body,button){
      if(sending)return;sending=true;busy(button,true);clearTimeout(timer);result.textContent='Sending…';
      try{const response=await fetch(location.href,{method:'POST',body,cache:'no-store'});if(!response.ok)throw new Error('Request rejected');const reply=new DOMParser().parseFromString(await response.text(),'text/html');result.textContent=reply.querySelector('p')?.textContent||'Request received.';await updateStatus();clearTimeout(timer);timer=setTimeout(poll,1500);}
      catch(error){result.textContent='Could not confirm the request. Check your connection before retrying.';timer=setTimeout(poll,5000);}
      finally{sending=false;busy(button,false);}
    }
    document.addEventListener('submit',event=>{event.preventDefault();const button=event.submitter;if(!button)return;const body=new URLSearchParams(new FormData(event.target));body.set(button.name,button.value);send(body,button);});
    document.getElementById('apkUpload').addEventListener('click',async function(){
      if(sending)return;const file=document.getElementById('apkFile').files[0];if(!file||!file.name.toLowerCase().endsWith('.apk')||file.size<1||file.size>41943040){result.textContent='Choose a FrameRevive APK no larger than 40 MiB.';return;}
      sending=true;busy(this,true);clearTimeout(timer);result.textContent='Uploading APK… Keep this page open.';
      try{const endpoint=new URL(location.href);endpoint.searchParams.set('action','uploadApk');const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/vnd.android.package-archive'},body:file,cache:'no-store'});if(!response.ok)throw new Error('Upload rejected');const reply=new DOMParser().parseFromString(await response.text(),'text/html');result.textContent=reply.querySelector('p')?.textContent||'Upload finished. Check update status.';await updateStatus();}
      catch(error){result.textContent='Upload interrupted. Check update status before trying again.';timer=setTimeout(poll,5000);}
      finally{sending=false;busy(this,false);}
    });
    document.getElementById('importButton').addEventListener('click',async function(){
      if(sending)return;const file=document.getElementById('sessionFile').files[0];if(!file){result.textContent='Choose your exported cookies.txt file first.';return;}if(file.size>200000){result.textContent='Export a dedicated Google Photos session smaller than 200 KB.';return;}try{await send(new URLSearchParams({action:'importSession',session:await file.text()}),this);}catch(error){result.textContent='Could not read the selected file.';}
    });
    document.getElementById('copyDiagnostics').addEventListener('click',async()=>{
      const text=document.getElementById('diagnosticReport').textContent;
      try{if(!navigator.clipboard||!window.isSecureContext)throw new Error('Clipboard fallback');await navigator.clipboard.writeText(text);result.textContent='Diagnostics copied. Private links and credentials are excluded.';}
      catch(error){const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.top='0';area.style.left='0';area.style.opacity='0';document.body.appendChild(area);area.select();let copied=false;try{copied=document.execCommand('copy');}catch(ignored){}area.remove();result.textContent=copied?'Diagnostics copied. Private links and credentials are excluded.':'Select the diagnostics text above and copy it manually.';}
    });
    timer=setTimeout(poll,4000);
    """.trimIndent()
}
